{'code': "import qgis.utils
from qgis.PyQt.QtWidgets import QMenu, QToolBar, QAction, QToolButton
pl = qgis.utils.plugins['StreetView']
mw = iface.mainWindow()
pa = getattr(pl, 'action', None)
out = []
for a in mw.findChildren(QAction):
    t = a.text() or ''
    if 'street' in t.lower() or 'ストリート' in t:
        conts = []
        for w in a.associatedObjects():
            if isinstance(w, QMenu):
                conts.append('QMenu:%s [%s]' % (w.title(), w.objectName()))
            elif isinstance(w, QToolBar):
                conts.append('QToolBar:%s [%s]' % (w.windowTitle(), w.objectName()))
            elif isinstance(w, QToolButton):
                conts.append('QToolButton:%s' % (w.text() or w.toolTip()))
            else:
                conts.append(w.metaObject().className())
        out.append({'text': t, 'enabled': a.isEnabled(), 'visible': a.isVisible(), 'toolTip': a.toolTip(), 'is_plugin_action': a is pa, 'containers': conts})
result = out"}
